(function(){"use strict";const lecture={"id":"ec214-l21","label":"Lecture 2.1 • Macroeconomic Indicators: GDP","description":"GDP measurement, nominal/real output, price indexes and living-standard interpretation.","cumulativeId":"ec214-l21-full-v1","cumulativeLabel":"Full Lecture • Lecture 2.1","parts":[{"id":"ec214-l21-definition-v1","label":"Part 1 • GDP Definition, Scope & Counting Rules","description":"VALUE / WHAT / WHERE / WHEN, final goods, domestic production and inclusion traps.","cards":[{"id":"gdp-def","front":"Define GDP.","back":"Market value of all final goods and services produced within a country in a given time period."},{"id":"value","front":"What does VALUE mean in the GDP definition?","back":"Measure production at market value; nominal GDP sums price × quantity of final products."},{"id":"what-final","front":"What does WHAT mean in the GDP definition?","back":"Count final goods and services, not intermediate goods separately."},{"id":"double-count","front":"Why are intermediate goods excluded from GDP?","back":"To avoid counting the same production more than once."},{"id":"value-added","front":"How can intermediate production be handled without double counting?","back":"Count final value or equivalently sum value added at each production stage."},{"id":"where","front":"What does WHERE mean in GDP?","back":"Production must occur within the country; owner nationality does not determine GDP."},{"id":"when","front":"What does WHEN mean in GDP?","back":"Production must occur in the specified period, such as the quarter or year."},{"id":"stocks-bonds","front":"Are purchases of stocks and bonds counted in GDP?","back":"No. The financial-asset purchase itself is not current production."},{"id":"new-home","front":"Where is a new home counted in GDP expenditure?","back":"Investment (I), not household Consumption."},{"id":"firm-software","front":"Can a firm purchase be a final capital good?","back":"Yes. If it is long-lived productive capital, it can count as investment rather than intermediate use."},{"id":"gdp-gnp","front":"What is the basic GDP vs GNP distinction?","back":"GDP follows production location; GNP-type logic follows nationality/residency of productive resources."},{"id":"final-trap","front":"Does 'final good' simply mean bought by a person?","back":"No. A firm can buy a final capital good such as machinery."}]},{"id":"ec214-l21-expenditure-v1","label":"Part 2 • Expenditure Approach & Circular Flow","description":"C + I + G + NX, transfers, imports and expenditure=income.","cards":[{"id":"formula","front":"State the expenditure-approach GDP formula.","back":"GDP = C + I + G + (X − M)."},{"id":"c","front":"What is Consumption (C)?","back":"Household spending on goods and services, except new housing."},{"id":"i","front":"What is Investment (I)?","back":"Capital equipment, inventories, structures, and new housing."},{"id":"inventory","front":"Why are inventories counted as investment?","back":"They are current production not yet sold to a final user."},{"id":"g","front":"What is Government purchases (G)?","back":"Government spending on currently produced goods and services."},{"id":"nx","front":"What are net exports (NX)?","back":"Exports minus imports: X − M."},{"id":"transfer","front":"Why is a transfer payment not counted in G?","back":"It is not payment for a currently produced good or service."},{"id":"transfer-spend","front":"If a household later spends a transfer, where is that activity counted?","back":"At the actual final expenditure, such as C; counting the transfer too would double count."},{"id":"imports","front":"Why are imports subtracted in NX?","back":"C, I, or G may include spending on imports; subtracting M removes foreign production from domestic GDP."},{"id":"circular","front":"What equality does the circular-flow approach emphasize?","back":"For the whole economy, Expenditure = Income."},{"id":"why-exp-income","front":"Why does expenditure equal income economy-wide?","back":"Every buyer’s spending becomes a seller’s income."}]},{"id":"ec214-l21-income-real-v1","label":"Part 3 • Income Approach, Nominal/Real GDP & Deflator","description":"Factor incomes, market adjustments, base-year logic and price/output separation.","cards":[{"id":"income-approach","front":"What does the income approach measure?","back":"GDP from income paid to factors of production, adjusted to align with market-value GDP."},{"id":"factor-income","front":"Match factors to income in the income approach.","back":"Labor→wages; Land→rent; Capital→interest; Entrepreneurship→profit."},{"id":"comp-employees","front":"What is compensation of employees?","back":"Labor compensation, broader than only take-home pay."},{"id":"net-operating","front":"What does net operating surplus collect?","back":"Other factor incomes such as interest, rent, profits, and proprietors’ income."},{"id":"market-adjust","front":"Why are market adjustments added on the income side?","back":"Items such as indirect taxes net of subsidies and depreciation align factor income with GDP at market value."},{"id":"nominal","front":"How is nominal GDP calculated?","back":"Current-year prices × current-year quantities."},{"id":"real","front":"How is real GDP calculated?","back":"Base-year prices × current-year quantities."},{"id":"real-purpose","front":"Why use real GDP?","back":"Holding prices fixed makes changes mainly reflect physical production, not inflation."},{"id":"nominal-trap","front":"Can higher nominal GDP occur even if real output falls?","back":"Yes. Rising prices can raise nominal GDP despite lower physical production."},{"id":"base-year","front":"What is true of nominal and real GDP in the base year?","back":"They are equal because both use the same prices and quantities."},{"id":"deflator","front":"State the GDP deflator formula.","back":"GDP Deflator = Nominal GDP ÷ Real GDP × 100."},{"id":"deflator-meaning","front":"What does the GDP deflator measure?","back":"A price-level index for goods and services included in domestic GDP."}]},{"id":"ec214-l21-living-v1","label":"Part 4 • Real GDP, Per Capita, PPP & Limits","description":"Living-standard comparisons and what GDP misses.","cards":[{"id":"real-time","front":"What is real GDP useful for over time?","back":"Tracking changes in real production."},{"id":"per-capita","front":"Why use real GDP per person?","back":"To compare production/living-standard output per individual without country size dominating."},{"id":"per-capita-formula","front":"State the GDP per capita formula.","back":"GDP per capita = GDP ÷ Population."},{"id":"market-fx","front":"Why can market-exchange-rate conversion mislead cross-country comparisons?","back":"It does not automatically adjust for different local price levels."},{"id":"ppp","front":"What does Purchasing Power Parity (PPP) adjust for?","back":"Differences in price levels and purchasing power across countries."},{"id":"low-dollar-trap","front":"Does lower dollar-converted GDP per person always mean lower living standards?","back":"No. Local prices and purchasing power can differ substantially."},{"id":"household-prod","front":"What GDP limitation involves household production?","back":"Useful non-market household production can be omitted."},{"id":"underground","front":"What GDP limitation involves the underground economy?","back":"Unreported production can occur without appearing in official GDP."},{"id":"health","front":"Does GDP directly measure health and life expectancy?","back":"No. They matter for well-being but are not directly captured by GDP."},{"id":"leisure","front":"Does higher GDP automatically mean more leisure or well-being?","back":"No. Leisure time is not directly captured by GDP."},{"id":"environment","front":"Can GDP rise while environmental quality worsens?","back":"Yes. GDP does not directly measure environmental quality."},{"id":"freedom-justice","front":"Does GDP measure political freedom or social justice?","back":"No. These are important well-being dimensions outside GDP."},{"id":"country-size-trap","front":"Can you infer people are better off because their country has larger GDP?","back":"No. Consider population and price-level/PPP differences at minimum."}]}]};const root=window.D_STUDY_FLASHCARD_BANKS=window.D_STUDY_FLASHCARD_BANKS||{};const b=root.ec214||(root.ec214={title:"EC214 Complete Lecture Flashcards",bankVersion:"ec214-v13.14",lectures:[]});b.lectures=Array.isArray(b.lectures)?b.lectures:[];b.lectures=b.lectures.filter(function(x){return x&&x.id!==lecture.id});b.lectures.push(lecture);})();